/* Visual Hierarchy through CSS */
.page-title {
  font-size: 3rem;    /* Dominant: read first */
  font-weight: 800;
  color: #ffffff;
}
.section-label {
  font-size: 0.7rem;  /* Subordinate: read last */
  letter-spacing: 3px;
  color: #888888;
  text-transform: uppercase;
}
.body-text {
  font-size: 1rem;    /* Mid-tier: supporting context */
  color: #cccccc;
  line-height: 1.7;
}

/* 60-30-10 rule in CSS variables */
:root {
  /* 60% — Dominant Background */
  --color-base: hsl(240, 15%, 8%);

  /* 30% — Secondary Surfaces */
  --color-surface: hsl(240, 12%, 14%);

  /* 10% — Accent (CTAs, highlights) */
  --color-accent: hsl(175, 100%, 60%);

  /* Semantic feedback colors */
  --color-success: hsl(140, 70%, 45%);
  --color-danger: hsl(0, 80%, 55%);
  --color-warning: hsl(38, 90%, 50%);
}

/* Modular type scale (ratio 1.25) */
:root {
  --text-xs: 0.64rem;    /* 10.24px */
  --text-sm: 0.8rem;     /* 12.8px */
  --text-base: 1rem;     /* 16px */
  --text-lg: 1.25rem;    /* 20px */
  --text-xl: 1.563rem;   /* 25px */
  --text-2xl: 1.953rem;  /* 31px */
  --text-3xl: 2.441rem;  /* 39px */
  --text-4xl: 3.052rem;  /* 49px */
}

body {
  font-family: 'Inter', sans-serif;
  font-size: var(--text-base);
  line-height: 1.6;
}

/* Wireframe structure translated to CSS layout */

/* Wireframe: [ HEADER ] */
.app-header {
  height: 60px;
  border-bottom: 1px solid var(--color-surface);
}

/* Wireframe: [ SIDEBAR | MAIN ] */
.app-shell {
  display: grid;
  grid-template-columns: 240px 1fr;
}

/* Wireframe: [ CARD GRID ] */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  padding: 20px;
}

/* Loading skeleton animation */
@keyframes skeleton-pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 0.9; }
}
.skeleton {
  background: #333;
  border-radius: 4px;
  animation: skeleton-pulse 1.5s ease-in-out infinite;
}

/* Form field focus interaction */
.field-input {
  border-bottom: 2px solid #444;
  transition: border-color 0.25s ease;
  outline: none;
}
.field-input:focus {
  border-color: #00ffcc;
}

/* Design Token System */
:root {
  /* Color Tokens */
  --token-color-primary: hsl(175, 100%, 50%);
  --token-color-danger: hsl(0, 80%, 55%);

  /* Spacing Scale */
  --token-space-1: 4px;
  --token-space-2: 8px;
  --token-space-4: 16px;
  --token-space-6: 24px;
  --token-space-8: 32px;

  /* Radius Scale */
  --token-radius-sm: 4px;
  --token-radius-md: 8px;
  --token-radius-full: 9999px;

  /* Type Tokens */
  --token-font-sans: 'Inter', system-ui, sans-serif;
  --token-font-mono: 'Share Tech Mono', monospace;
}
